class Solution {
public:
    vector<int> resultsArray(vector<int>& nums, int k) {
        int n = nums.size();
        vector<int> res(n - k + 1);
        int bad = 0;
        for (int i = 0; i + 1 < k; ++i) {
            if (nums[i + 1] != nums[i] + 1) ++bad;
        }
        res[0] = (bad == 0) ? nums[k - 1] : -1;
        for (int i = 1; i + k - 1 < n; ++i) {
            if (k > 1) {
                if (nums[i] != nums[i - 1] + 1) --bad;
                if (nums[i + k - 1] != nums[i + k - 2] + 1) ++bad;
            }
            res[i] = (bad == 0) ? nums[i + k - 1] : -1;
        }
        return res;
    }
};
